            "text": "875/125 mg orally twice daily; day 3 of oral treatment after 2 days IV."
          }
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-2",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Paracetamol (Panadol)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "1 g every 6 hours as needed.",
            "asNeededBoolean": true,
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 1,
                  "unit": "g"
                }
              }
            ]
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-3",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-3",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Prenatal multivitamin"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-4",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-4",
        "status": "completed",
        "medicationCodeableConcept": {
          "text": "Gentamicin"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "IV treatment as part of a 48-hour course."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-5",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-5",
        "status": "completed",
        "medicationCodeableConcept": {
          "text": "Metronidazole"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "IV treatment as part of a 48-hour course."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-6",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-6",
        "status": "completed",
        "medicationCodeableConcept": {
          "text": "Amoxicillin"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "IV treatment as part of a 48-hour course."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Amoxicillin/clavulanate 875/125 mg (Augmentin Duo Forte)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Continue 875/125 mg orally twice daily to at least 7 days total oral treatment after IV treatment. Consider extending to 10 days if still symptomatic on day 7.",
            "timing": {
              "repeat": {
                "frequency": 2,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "route": {
              "text": "oral"
            }
          }
        ]
      }
    }
  ]
}

